					t.Fatalf("current home reply: %+v, %v", receipt, err)
				}
			} else if err == nil {
				t.Fatal("untrusted or mismatched home reply authorized capacity")
			}
			if scenario != "missing pin" && scenario != "unavailable pin" {
				select {
				case err := <-responses:
					if err != nil {
						t.Fatal(err)
					}
