}
renamed := grant("ts-gru-1", "10.251.0.21", terrabase.Role, "web")
renamed.Generation, renamed.RequiresBinary, renamed.HostGrants[0].Controller = 3, 17, "controller-a"
if err := registry.validate(renamed); err != nil {
