func (r *runtimeObservability) recordHostLoad(load host.LoadSink, origin hostload.Origin, report hostload.Report, requests map[string]hostload.Request) error {
	var loadErr error
	if load != nil {
		loadErr = load(origin, report)
		if errors.Is(loadErr, authority.ErrFenced) {
			return loadErr
		}
	}
	usageErr := r.usage.Record(origin, report, requests)
	if load == nil {
		return usageErr
	}
	// Optional capacity history must not back off accepted autoscaler telemetry.
	if usageErr != nil {
		slog.Debug("capacity history discarded a host report", observability.ComponentKey, "capacity", "node", origin.Node, "error", usageErr)
	}
	return loadErr
}

telemetry_current.text:
func (t *hostTelemetry) current() bool {
	snapshot := t.fencer.Current()
	if !snapshot.CanMutate() {
		t.load.Reset()
		clear(t.managedRequests)
		clear(t.usagePoints)
		t.epoch = 0
		return false
	}
	if t.epoch != snapshot.Epoch {
		t.load.Reset()
		clear(t.managedRequests)
		clear(t.usagePoints)
		t.epoch = snapshot.Epoch
	}
	return true
}

telemetry_record.text:
func (t *hostTelemetry) record(origin hostload.Origin, report hostload.Report) error {
	t.mu.Lock()
	defer t.mu.Unlock()
	if !t.current() {
		return authority.ErrFenced
	}
	return t.load.Record(origin, report)
}

