func NewStore(region string) *Store {
	return &Store{Region: region, History: observability.NewHistory(observability.HistoryConfig{Interval: 5 * time.Second, StaleAfter: Retention}), last: map[string]time.Time{}}
}

capacity_record.text:
func (s *Store) recordAt(now time.Time, origin hostload.Origin, report hostload.Report, requests map[string]hostload.Request, committed bool) error {
	if origin.Cell != s.Region || origin.Node == "" {
		return errors.New("capacity report origin mismatch")
	}
	if err := report.Validate(); err != nil {
		return err
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if !committed && now.Sub(s.last[origin.Node]) < hostload.DefaultMinInterval {
		return hostload.ErrTooFrequent
	}
	if committed && !s.last[origin.Node].IsZero() && !now.After(s.last[origin.Node]) {
		return errors.New("committed capacity history is out of order")
	}
	for node, at := range s.last {
		if now.Sub(at) > Retention {
			delete(s.last, node)
		}
	}
	nodeLimit := 256
	if committed {
		nodeLimit = 4096
	}
	if _, ok := s.last[origin.Node]; !ok && len(s.last) >= nodeLimit {
		return errors.New("capacity node limit reached")
	}
	s.last[origin.Node] = now
	var samples []observability.Sample
	add := func(service, metric string, value float64) {
		samples = append(samples, observability.Sample{Metric: "capacity_" + metric, Labels: observability.L("node", origin.Node, "service", service, "environment", origin.Environment), Value: value})
	}
	var cpuRequest, memoryRequest float64
	requestsKnown := true
	for _, role := range report.Roles {
		request, known := requests[role.Role]
		if known {
			add(role.Role, "cpu_request", request.CPUCores)
			add(role.Role, "memory_request", float64(request.MemoryBytes))
			cpuRequest += request.CPUCores
			memoryRequest += float64(request.MemoryBytes)
		} else {
			requestsKnown = false
		}
		if role.CPUCores != nil {
			add(role.Role, "cpu_usage", *role.CPUCores)
		}
		if role.MemoryBytes != nil {
			add(role.Role, "memory_usage", float64(*role.MemoryBytes))
		}
		if role.LimitsRead {
			cpuLimit, memoryLimit := float64(report.Host.CPUCores), float64(report.Host.MemoryBytes)
			if role.CPULimit != nil {
				cpuLimit = *role.CPULimit
			}
			if role.MemoryLimit != nil {
				memoryLimit = float64(*role.MemoryLimit)
			}
			if cpuLimit > 0 {
				add(role.Role, "cpu_limit", cpuLimit)
				if role.CPUCores != nil {
					add(role.Role, "cpu_headroom", max(0, cpuLimit-*role.CPUCores))
				}
			}
			if memoryLimit > 0 {
				add(role.Role, "memory_limit", memoryLimit)
				if role.MemoryBytes != nil {
					add(role.Role, "memory_headroom", max(0, memoryLimit-float64(*role.MemoryBytes)))
				}
			}
		}
	}
	if requestsKnown {
		add("", "cpu_request", cpuRequest)
		add("", "memory_request", memoryRequest)
	}
	if report.Host.CPUCores > 0 {
		limit := float64(report.Host.CPUCores)
		add("", "cpu_limit", limit)
		if report.Host.CPU != nil {
			add("", "cpu_usage", limit**report.Host.CPU)
			add("", "cpu_headroom", limit*(1-*report.Host.CPU))
		}
	}
	if report.Host.MemoryBytes > 0 {
		limit := float64(report.Host.MemoryBytes)
		add("", "memory_limit", limit)
		if report.Host.Memory != nil {
			add("", "memory_usage", limit**report.Host.Memory)
			add("", "memory_headroom", limit*(1-*report.Host.Memory))
		}
	}
	s.History.Append(now, samples)
	return nil
}

history_append.text:
func (history *History) Append(at time.Time, samples []Sample) {
	millis := at.UnixMilli()
	history.mu.Lock()
	defer history.mu.Unlock()
	minute := millis / time.Minute.Milliseconds()
	history.newestMinute = max(history.newestMinute, minute)
	oldestMinute := history.newestMinute - int64(rawRetention/time.Minute)
	for at := range history.dropMinutes {
		if at < oldestMinute {
			delete(history.dropMinutes, at)
		}
	}
	// Prune first, so series that stopped reporting free their slots.
	stale := millis - history.config.StaleAfter.Milliseconds()
	for key, current := range history.series {
		if current.last < stale {
			delete(history.series, key)
		}
	}
	for _, sample := range samples {
		if math.IsNaN(sample.Value) || math.IsInf(sample.Value, 0) || sample.Metric == "" {
			continue
		}
		labels := sortedLabels(sample.Labels)
		key := seriesKey(sample.Metric, labels)
		current, ok := history.series[key]
		if !ok {
			if len(history.series) >= history.config.MaxSeries {
				history.dropped++
				if minute >= oldestMinute {
					history.dropMinutes[minute] = true
				}
				historyDropped.Inc()
				continue
			}
			current = history.newSeries(sample.Metric, labels, sample.Counter)
			history.series[key] = current
		}
		if millis < current.last {
			continue
		}
		// A counter's growth since its previous raw sample, reset-correct:
		// a decrease is a restart that counted again from zero.
		increase, counted := 0.0, false
		if current.counter && current.sampled {
			increase, counted = sample.Value-current.lastValue, true
			if increase < 0 {
				increase = sample.Value
			}
		}
		current.last, current.lastValue, current.sampled = millis, sample.Value, true
		for _, name := range []string{TierRaw, Tier1m, Tier5m, Tier1h} {
			current.tiers[name].add(millis, sample.Value, increase, counted)
		}
		historySamples.Inc()
	}
}

history_stats.text:
func (history *History) Stats() HistoryStats {
	history.mu.RLock()
	defer history.mu.RUnlock()
	return HistoryStats{Series: len(history.series), Dropped: history.dropped}
}

aggregator_record.text:
func (a *Aggregator) record(origin Origin, report Report, requests map[string]Request) error {
	if err := report.Validate(); err != nil {
		return err
	}
	now := a.config.Now()
	node, known := a.nodes[origin.Node]
	if known && now.Sub(node.latest.At) < a.config.MinInterval {
		return ErrTooFrequent
	}
	if !known {
		if len(a.nodes) >= maxNodes {
			// Full: forget every node that is no longer reporting, even if
			// a long window could still use its older samples.
			a.pruneLocked(now, a.config.StaleAfter)
		}
		if len(a.nodes) >= maxNodes {
			return ErrTooManyNodes
		}
		node = &nodeState{store: autoscale.NewWindowStore(nodeRetention, a.nodePoints()),
			series: make(map[seriesKey]time.Time)}
		a.nodes[origin.Node] = node
	}
	node.latest = NodeLoad{Origin: origin, At: now, Report: report}
	// Recording under the aggregator lock keeps one node's samples in
	// receive order and its store from being pruned mid-record.
	for _, role := range report.Roles {
		target := autoscale.Target{Cell: origin.Cell, Environment: origin.Environment, Role: role.Role}
		for name, value := range roleSignals(role, report.Host, requests[role.Role]) {
			node.store.Record(target, name, autoscale.Sample{At: now, Value: value})
			key := seriesKey{target: target, signal: name}
			node.series[key] = now
			current := a.runs[key]
			switch gap := now.Sub(current.last); {
			case current.last.IsZero() || gap > a.config.StaleAfter:
				current.since, current.holes = now, nil
			case gap > 2*a.config.MinInterval:
				// Samples arrive in receive order, so holes stay sorted and
				// the expired ones are at the front.
				expired := 0
				for expired < len(current.holes) && now.Sub(current.holes[expired].end) > nodeRetention {
					expired++
				}
				current.holes = append(current.holes[expired:], hole{end: now, length: gap})
			}
			current.last = now
			a.runs[key] = current
		}
	}
	return nil
}

aggregator_nodes.text:
func (a *Aggregator) Nodes() []NodeLoad {
	now := a.config.Now()
	a.mu.Lock()
	a.pruneLocked(now, nodeRetention)
	out := make([]NodeLoad, 0, len(a.nodes))
	for _, node := range a.nodes {
		if now.Sub(node.latest.At) <= a.config.StaleAfter {
			out = append(out, node.latest)
		}
	}
	a.mu.Unlock()
	slices.SortFunc(out, func(x, y NodeLoad) int { return strings.Compare(x.Origin.Node, y.Origin.Node) })
	return out
}

reservation_request.text:
func (r *capacityReservations) request(ctx context.Context, action string, request capacityReservationRequest) (budget.Reservation, error) {
	response, err := r.exchange(ctx, action, request)
	if err != nil {
		return budget.Reservation{}, err
	}
	if response.Pool != nil || response.Receipt == nil || response.Receipt.OperationID != request.Request.OperationID || response.Receipt.RecipeSHA256 != request.Recipe.SHA256() {
		return budget.Reservation{}, fmt.Errorf("%w: home response differs from the original capacity reservation", nodescale.ErrCapacityPending)
	}
	return *response.Receipt, nil
}

reservation_exchange.text:
func (r *capacityReservations) exchange(ctx context.Context, action string, request capacityReservationRequest) (capacityReservationResponse, error) {
	if r == nil || r.conn == nil {
		return capacityReservationResponse{}, fmt.Errorf("%w: home capacity authority is unavailable", nodescale.ErrCapacityPending)
	}
	if r.homeKey == nil {
		return capacityReservationResponse{}, fmt.Errorf("%w: independently verified current home response key is unavailable", nodescale.ErrCapacityPending)
	}
	public, err := r.homeKey(ctx)
	if err != nil || len(public) != ed25519.PublicKeySize {
		return capacityReservationResponse{}, fmt.Errorf("%w: current home response authority is unavailable: %v", nodescale.ErrCapacityPending, err)
	}
	request.Nonce = entityid.New()
	reply := protocol.CapacityReservationReplySubject(r.cell, r.user, request.Nonce)
	if reply == "" {
		return capacityReservationResponse{}, errors.New("capacity reply identity is invalid")
	}
	ctx, cancel := context.WithTimeout(ctx, 100*time.Second)
	defer cancel()
	subscription, err := r.conn.SubscribeSync(reply)
	if err != nil {
		return capacityReservationResponse{}, err
	}
	defer subscription.Unsubscribe()
	if err := r.conn.FlushWithContext(ctx); err != nil {
		return capacityReservationResponse{}, err
	}
	wire, err := protocol.EncodeJSON(request)
	if err != nil {
		return capacityReservationResponse{}, err
	}
	if err := r.conn.PublishRequest(protocol.CapacityReservationSubject(r.cell, action), reply, wire); err != nil {
		return capacityReservationResponse{}, err
	}
	message, err := subscription.NextMsgWithContext(ctx)
	if err != nil {
		return capacityReservationResponse{}, err
	}
	var envelope protocol.Envelope
	if err := protocol.DecodeStrict(message.Data, &envelope, 128<<10); err != nil {
		return capacityReservationResponse{}, err
	}
	currentPublic, err := r.homeKey(ctx)
	if err != nil {
		return capacityReservationResponse{}, fmt.Errorf("%w: current home response authority: %v", nodescale.ErrCapacityPending, err)
	}
	if !slices.Equal(public, currentPublic) {
		return capacityReservationResponse{}, errors.New("home response authority changed during the original request")
	}
	if envelope.Epoch == 0 {
		return capacityReservationResponse{}, errors.New("capacity response lacks home authority epoch")
	}
	if err := protocol.VerifyEnvelope(envelope, protocol.EnvelopeScope{Region: r.cell, Kind: "capacity." + action + ".response",
		Actor: "capacity-home", OperationID: request.Nonce, Epoch: envelope.Epoch}, public, time.Now().UTC(),
		protocol.VerifyPolicy{MaxLifetime: 30 * time.Second}); err != nil {
		return capacityReservationResponse{}, fmt.Errorf("verify current home capacity response: %w", err)
	}
	var response capacityReservationResponse
	if err := protocol.DecodeStrict(envelope.Payload, &response, 112<<10); err != nil {
		return capacityReservationResponse{}, err
	}
	if response.Nonce != request.Nonce || response.Error != "" {
		return capacityReservationResponse{}, fmt.Errorf("%w: home capacity reservation: %s", nodescale.ErrCapacityPending, response.Error)
	}
	return response, nil
}

worker_auth.text:
func (r *capacityReservations) authorizeWorker(ctx context.Context, recipe nodescale.Recipe, compartment string) (region.VerifiedWorkerRecipe, error) {
	if r == nil || r.workers == nil {
		return region.VerifiedWorkerRecipe{}, fmt.Errorf("%w: independently signed worker role and bootstrap authority is unavailable", nodescale.ErrCapacityPending)
	}
	verified, err := r.workers.AuthorizeWorkerRecipe(ctx, workerCandidate(recipe, compartment, r.environment))
	if err != nil {
		return region.VerifiedWorkerRecipe{}, fmt.Errorf("%w: independent worker recipe: %v", nodescale.ErrCapacityPending, err)
	}
	if err := verified.Match(workerCandidate(recipe, compartment, r.environment)); err != nil {
		return region.VerifiedWorkerRecipe{}, fmt.Errorf("%w: independent worker recipe: %v", nodescale.ErrCapacityPending, err)
	}
	if err := verified.Revalidate(ctx); err != nil {
		return region.VerifiedWorkerRecipe{}, err
	}
	return verified, nil
}

worker_base.text:
func (r *capacityReservations) workerBase(ctx context.Context, role, architecture string) (nodescale.Recipe, string, error) {
	if r == nil || r.workers == nil {
		return nodescale.Recipe{}, "", fmt.Errorf("%w: independently signed worker profiles are unavailable", nodescale.ErrCapacityPending)
	}
	caWire, err := readBoundedConfigFile(r.caFile)
	if err != nil {
		return nodescale.Recipe{}, "", err
	}
	profiles, err := r.workers.WorkerRecipes(ctx, strings.ToUpper(r.cell), role, caWire)
	if err != nil {
		return nodescale.Recipe{}, "", err
	}
	var base nodescale.Recipe
	compartment := ""
	for _, profile := range profiles {
		if !profile.IsVerified() {
			return nodescale.Recipe{}, "", fmt.Errorf("%w: worker profile is unverified", nodescale.ErrCapacityPending)
		}
		worker := profile.Recipe()
		if architecture != "" && worker.Architecture != architecture {
			continue
		}
		if err := profile.Revalidate(ctx); err != nil {
			return nodescale.Recipe{}, "", err
		}
		if compartment == "" {
			base = nodescale.Recipe{Cell: worker.Cell, Capacity: nodescale.Capacity{Role: worker.Role, Architecture: worker.Architecture, Shape: worker.Shape},
				SubnetID: worker.SubnetID, NSGIDs: worker.NSGIDs, ImageID: worker.ImageID, OCPUs: float32(worker.OCPUs), MemoryGB: float32(worker.MemoryGB), Metadata: worker.Metadata}
			compartment = worker.CompartmentID
		} else if worker.CompartmentID != compartment || worker.SubnetID != base.SubnetID || worker.OCPUs != float64(base.OCPUs) ||
			worker.MemoryGB != float64(base.MemoryGB) || worker.BootGB != nodescale.BootVolumeGB || !maps.Equal(worker.Metadata, base.Metadata) ||
			!slices.Equal(slices.Sorted(slices.Values(worker.NSGIDs)), slices.Sorted(slices.Values(base.NSGIDs))) {
			return nodescale.Recipe{}, "", fmt.Errorf("%w: worker profiles disagree on regional placement", nodescale.ErrCapacityPending)
		}
		base.AvailabilityDomains = append(base.AvailabilityDomains, worker.AvailabilityDomains...)
	}
	if compartment == "" {
		return nodescale.Recipe{}, "", fmt.Errorf("%w: no qualified worker profile matches isolation role and architecture", nodescale.ErrCapacityPending)
	}
	base.AvailabilityDomains = slices.Compact(slices.Sorted(slices.Values(base.AvailabilityDomains)))
	return base, compartment, base.Validate()
}

capacity_prepare.text:
func (r *capacityReservations) prepare(ctx context.Context, operationID string, recipe nodescale.Recipe, compartment string) (capacityReservationRequest, error) {
	request := capacityReservationRequest{Recipe: recipe}
	worker, err := r.authorizeWorker(ctx, recipe, compartment)
	if err != nil {
		return request, err
	}
	reader, proof, snapshot, err := r.facts(ctx)
	if err != nil {
		return request, fmt.Errorf("%w: current complete spending facts: %v", nodescale.ErrCapacityPending, err)
	}
	if err := sameWorkerSpendingGrant(worker, proof); err != nil {
		return request, err
	}
	cell := ""
	for _, scope := range proof.Footprint().Regions {
		if strings.EqualFold(scope.Cell, recipe.Cell) {
			cell = scope.Cell
		}
	}
	quote, err := reader.Quote(ctx, proof.Footprint(), cell, compartment, recipe.Capacity.Shape,
		float64(recipe.OCPUs), float64(recipe.MemoryGB), nodescale.BootVolumeGB)
	if err != nil {
		return request, err
	}
	inputs, err := r.imageInputs(ctx, recipe.Capacity.Role)
	if err != nil {
		return request, err
	}
	for _, input := range inputs {
		if input.Expected.OCIImageOCID != recipe.ImageID || input.Expected.Architecture != recipe.Capacity.Architecture {
			continue
		}
		_, expires, err := r.qualify(ctx, input)
		if err != nil {
			continue
		}
		for _, deadline := range []time.Time{quote.ExpiresAt(), snapshot.ExpiresAt, proof.ExpiresAt()} {
			if deadline.Before(expires) {
				expires = deadline
			}
		}
		if deadline := worker.Profile().ExpiresAt(); deadline.Before(expires) {
			expires = deadline
		}
		request.Image = input
		request.Request = budget.ReservationRequest{OperationID: operationID, RecipeSHA256: recipe.SHA256(), Cell: cell,
			CompartmentID: compartment, Shape: recipe.Capacity.Shape, OCPUs: float64(recipe.OCPUs), MemoryGB: float64(recipe.MemoryGB),
			BootGB: nodescale.BootVolumeGB, MonthlyCents: quote.MonthlyCents(), FactsExpireAt: expires}
		return request, nil
	}
	return request, fmt.Errorf("%w: no currently qualified exact host image and isolation role", nodescale.ErrCapacityPending)
}

foundation_profiles.text:
func (r FoundationResolver) WorkerProfiles(ctx context.Context, cell, role string) ([]VerifiedWorkerProfile, error) {
	reader, ok := r.Footprint.(*SignedFootprint)
	if !ok {
		return nil, errors.New("worker profiles require the independent signed foundation reader")
	}
	return reader.WorkerProfiles(ctx, cell, role)
}

foundation_auth.text:
func (r FoundationResolver) AuthorizeWorkerRecipe(ctx context.Context, candidate WorkerRecipe) (VerifiedWorkerRecipe, error) {
	profiles, err := r.WorkerProfiles(ctx, strings.ToUpper(candidate.Cell), candidate.Role)
	if err != nil {
		return VerifiedWorkerRecipe{}, err
	}
	bundle, err := hostenroll.ParsePublicBundle([]byte(candidate.Metadata[hostboot.EnrollmentMetadataKey]))
	if err != nil {
		return VerifiedWorkerRecipe{}, err
	}
	for _, profile := range profiles {
		if profile.profile.Architecture != candidate.Architecture || profile.profile.Shape != candidate.Shape {
			continue
		}
		source, err := profile.reader.workerSource(ctx, profile.profile.Cell)
		if err != nil {
			return VerifiedWorkerRecipe{}, err
		}
		recipe, err := profile.Bind(ctx, source, []byte(bundle.CAPEM))
		if err != nil {
			return VerifiedWorkerRecipe{}, err
		}
		if err := recipe.Match(candidate); err != nil {
			return VerifiedWorkerRecipe{}, err
		}
		if err := recipe.Revalidate(ctx); err != nil {
			return VerifiedWorkerRecipe{}, err
		}
		return recipe, nil
	}
	return VerifiedWorkerRecipe{}, errors.New("worker candidate has no exact signed role/architecture/shape policy")
}

foundation_recipes.text:
func (r FoundationResolver) WorkerRecipes(ctx context.Context, cell, role string, caWire []byte) ([]VerifiedWorkerRecipe, error) {
	profiles, err := r.WorkerProfiles(ctx, cell, role)
	if err != nil {
		return nil, err
	}
	source, err := profiles[0].reader.workerSource(ctx, cell)
	if err != nil {
		return nil, err
	}
	recipes := make([]VerifiedWorkerRecipe, 0, len(profiles))
	for _, profile := range profiles {
		recipe, err := profile.Bind(ctx, source, caWire)
		if err != nil {
			return nil, err
		}
		recipes = append(recipes, recipe)
	}
	return recipes, nil
}

registry_new.text:
func newSpecRegistry(cfg Config, memberRole string) (*specRegistry, error) {
	r := &specRegistry{cell: cfg.NATS.Cell, fixed: map[string]WorkloadProfile{},
		signers: slices.SortedFunc(slices.Values(cfg.Controller.TrustedSigners), func(a, b TrustedSignerConfig) int {
			return strings.Compare(a.Actor, b.Actor)
		}), terraBaseCA: cfg.Controller.TerraBaseCACertFile != "",
		signedArtifactStore: cmp.Or(cfg.Controller.ArtifactStoreMaxBytes, delivery.DefaultArtifactStoreMaxBytes)}
	if cfg.NATS.Embedded != nil {
		r.artifactStoreLimit = cfg.NATS.Embedded.StoreLimitBytes() - specStoreHeadroomBytes
	}
	if _, signed := cfg.Controller.Workloads[terrabase.Role]; signed {
		r.terraBaseCA = true
	}
	if reconcile := cfg.Controller.OciReconcile; reconcile != nil {
		r.signedDesired, r.publicLB = reconcile.Desired, reconcile.PublicLB
	}
	if memberRole != "" {
		r.reserved = append(r.reserved, memberRole)
	}
	autoscaleConfig := cfg.Controller.Autoscale
	if err := r.loadTrust(cfg); err != nil {
		return nil, err
	}
	// Generation 0 is the signed config's generic workloads.
	r.current = cellspec.Spec{Schema: cellspec.Schema, Identity: r.identity, RequiresBinary: 1}
	for _, role := range slices.Sorted(maps.Keys(cfg.Controller.Workloads)) {
		profile := cfg.Controller.Workloads[role]
		if slices.Contains(r.reserved, role) || role == terrabase.Role {
			r.fixed[role] = profile
			continue
		}
		service := cellspec.Service{Role: role, Profile: profile}
		// Generation 0 reconciles exactly what the signed config already
		// reconciled.
		if autoscaleConfig != nil {
			for _, spec := range autoscaleConfig.Services {
				if spec.Role == role {
					service.Spec = &spec
				}
			}
		}
		r.current.Services = append(r.current.Services, service)
	}
	r.current.RequiresBinary = r.current.Level()
	return r, nil
}

registry_trust.text:
func (r *specRegistry) loadTrust(cfg Config) error {
	if cfg.Controller.SpecTrust != nil {
		return errors.New("production controller uses the image trust roots")
	}
	accepted, inputs, err := specAcceptedInputs()
	if err != nil {
		return fmt.Errorf("load accepted trust roots for cell specs: %w", err)
	}
	identity := cellspec.Identity{DeploymentID: accepted.DeploymentID,
		Cell: strings.ToLower(accepted.Cell), Environment: accepted.Environment}
	if identity.Cell != cfg.NATS.Cell {
		return errors.New("accepted trust cell differs from the controller cell")
	}
	if err := identity.Validate(); err != nil {
		return err
	}
	r.identity = identity
	return r.openRoots(inputs.Genesis, inputs.Chain, bootstrapstart.RootChainFile)
}

registry_open.text:
func (r *specRegistry) open(ctx context.Context, js jetstream.JetStream, replicas int) error {
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{Bucket: cellSpecBucket, History: 4,
		MaxValueSize: cellspec.MaxSignedBytes, Storage: jetstream.FileStorage, Replicas: replicas})
	if err != nil {
		return fmt.Errorf("open cell spec: %w", err)
	}
	r.kv = kv
	entry, err := kv.Get(ctx, cellSpecKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return nil
	}
	if err != nil {
		return fmt.Errorf("read cell spec: %w", err)
	}
	return r.load(entry)
}

registry_load.text:
func (r *specRegistry) load(entry jetstream.KeyValueEntry) error {
	if entry.Operation() != jetstream.KeyValuePut {
		slog.Error("cell spec record was removed; keeping the current spec", observability.ComponentKey, "cellspec")
		return errors.New("stored cell spec was removed")
	}
	verified, err := r.verify(entry.Value(), nil)
	if newer := (*cellspec.NewerBinaryError)(nil); errors.As(err, &newer) {
		slog.Warn("stored cell spec needs a newer binary; keeping the current spec", observability.ComponentKey, "cellspec",
			"revision", entry.Revision(), "generation", newer.Generation, "requires_binary", newer.RequiresBinary,
			"binary_level", cellspec.BinaryLevel)
		return err
	}
	if err != nil {
		slog.Error("stored cell spec rejected; keeping the current spec", observability.ComponentKey, "cellspec",
			"revision", entry.Revision(), "error", err)
		return fmt.Errorf("stored cell spec rejected: %w", err)
	}
	r.adopt(verified.Spec, entry.Revision())
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.revision < entry.Revision() {
		return errors.New("stored cell spec could not be adopted")
	}
	return nil
}

registry_adopt.text:
func (r *specRegistry) adopt(spec cellspec.Spec, revision uint64) {
	r.launches.Lock()
	defer r.launches.Unlock()
	r.mu.Lock()
	defer r.mu.Unlock()
	if revision <= r.revision {
		return
	}
	// A stored record only moves forward; an older signed spec written into
	// the record is a rollback, whatever its revision.
	if spec.Generation < r.current.Generation || spec.Generation == r.current.Generation && !sameSpec(spec, r.current) {
		slog.Error("stored cell spec would roll back the current spec; keeping it", observability.ComponentKey, "cellspec",
			"generation", spec.Generation, "current", r.current.Generation, "revision", revision)
		return
	}
	// The signers change first, and a spec whose signers are refused is not
	// adopted at all, so no consumer sees one generation's spec with
	// another's signers.
	if r.replaceSigners != nil {
		if err := r.replaceSigners(r.effectiveSigners(spec)); err != nil {
			slog.Error("stored cell spec signers refused; keeping the current spec", observability.ComponentKey, "cellspec",
				"generation", spec.Generation, "revision", revision, "error", err)
			return
		}
	}
	r.current, r.revision = spec, revision
	slog.Info("cell spec adopted", observability.ComponentKey, "cellspec", "generation", spec.Generation,
		"revision", revision, "roles", len(spec.Services))
	if r.changed != nil {
		profiles, specs := r.effectiveLocked()
		r.changed(profiles, specs)
	}
}

registry_verify.text:
func (r *specRegistry) verify(wire []byte, now *time.Time) (cellspec.Verified, error) {
	if r.roots == nil {
		return cellspec.Verified{}, errors.New("this controller has no cell spec trust roots")
	}
	var verified cellspec.Verified
	var err error
	// Stored records verify with the current roots too, so a replaced root
	// cannot write a spec; keepsStoredSpec keeps the stored spec valid.
	if now != nil {
		verified, err = cellspec.VerifyCurrent(wire, r.roots.current(), r.identity, *now)
	} else {
		verified, err = cellspec.VerifyHistorical(wire, r.roots.current(), r.identity)
	}
	if err != nil {
		return cellspec.Verified{}, err
	}
	// Host image receipts verify with every root the chain named, so a
	// rotation does not strand the images a replaced root qualified; the
	// leader admits new ones only under the current roots.
	if err := cellspec.VerifyHostImages(cellspec.Spec{}, verified.Spec, r.roots.historical(), nil); err != nil {
		return cellspec.Verified{}, err
	}
	return verified, r.validate(verified.Spec)
}

registry_validate.text:
func (r *specRegistry) validate(spec cellspec.Spec) error {
	if len(spec.Signers) != 0 {
		if _, err := newSignerSet(spec.Signers); err != nil {
			return fmt.Errorf("cell spec signers: %w", err)
		}
	}
	profiles := maps.Clone(r.fixed)
	var specs []workload.ServiceSpec
	for _, service := range spec.Services {
		if slices.Contains(r.reserved, service.Role) {
			return fmt.Errorf("role %q is owned by placement and stays in the signed controller config", service.Role)
		}
		if service.Role == terrabase.Role && (!r.terraBaseCA || service.Spec != nil) {
			return fmt.Errorf("service %q needs the signed TerraBase member CA and is never reconciled", service.Role)
		}
		for _, actor := range service.Releasers {
			if !slices.ContainsFunc(r.effectiveSigners(spec), func(signer TrustedSignerConfig) bool { return signer.Actor == actor }) {
				return fmt.Errorf("service %q releaser %q is not a trusted signer", service.Role, actor)
			}
		}
		profiles[service.Role] = service.Profile
		if service.Spec != nil {
			specs = append(specs, *service.Spec)
		}
	}
	if err := validateWorkloadProfiles(r.cell, profiles); err != nil {
		return err
	}
	if err := r.validateHostGrants(spec.HostGrants, profiles); err != nil {
		return err
	}
	if desired := spec.OCIDesired; desired != nil {
		if r.ociRegion == nil {
			return errors.New("desired OCI resources need the signed region config")
		}
		if _, _, err := desiredSets(*desired, string(r.ociRegion.Region), *r.ociRegion); err != nil {
			return err
		}
	}
	if fence, public := spec.ReleaseFence, r.publicLB; fence != nil && public != nil && fence.LoadBalancerID == public.LoadBalancerID {
		for _, set := range fence.BackendSets {
			if set.Name == public.BackendSet {
				// The reconciler would return a fenced backend to rotation.
				return fmt.Errorf("release_fence names backend set %q, which oci_reconcile.public_lb owns", set.Name)
			}
		}
	}
	limit, headroom := r.artifactStoreLimit, specStoreHeadroomBytes
	if spec.MachinesAPI != nil {
		limit, headroom = limit-machinesAPIStoreBytes, headroom+machinesAPIStoreBytes
	}
	if store := spec.ArtifactStore; store != nil && store.MaxBytes > limit {
		return fmt.Errorf("artifact_store max_bytes %d exceeds this controller's %d: its embedded NATS store_max_bytes less %d bytes for control state",
			store.MaxBytes, max(limit, 0), headroom)
	}
	return validateAutoscaleConfig(&AutoscaleConfig{Services: specs}, profiles)
}

registry_grants.text:
func (r *specRegistry) validateHostGrants(grants []cellspec.HostGrant, profiles map[string]WorkloadProfile) error {
	var members terrabase.Profile
	if effective, ok := profiles[terrabase.Role]; ok && len(effective.Env) != 0 {
		members, _ = terrabase.ParseProfile(effective.Env)
	}
	for _, grant := range grants {
		peer, member := members.Member(grant.Node, grant.PrivateIP)
		if member != slices.Contains(grant.Roles, terrabase.Role) || member && peer.Address.Addr().String() != grant.PrivateIP {
			return fmt.Errorf("host grant %q lists role %q exactly when %s lists the node at the grant's address",
				grant.Node, terrabase.Role, terrabase.EnvPeers)
		}
		for _, role := range grant.Roles {
			if _, ok := profiles[role]; !ok || slices.Contains(r.reserved, role) {
				return fmt.Errorf("host grant %q role %q has no service profile or belongs to placement", grant.Node, role)
			}
		}
	}
	return nil
}

registry_hostgrant.text:
func (r *specRegistry) hostGrant(node string) (cellspec.HostGrant, host.Capacity, bool) {
	if r == nil {
		return cellspec.HostGrant{}, host.Capacity{}, false
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	grant, ok := r.current.Grant(node)
	if !ok {
		return cellspec.HostGrant{}, host.Capacity{}, false
	}
	profiles, _ := r.effectiveLocked()
	var capacity host.Capacity
	for _, role := range grant.Roles {
		resources := profiles[role].Resources
		capacity.CPU += resources.CPU
		capacity.MemoryBytes += resources.MemoryBytes
		capacity.DiskBytes += resources.DiskBytes
	}
	return grant, capacity, true
}

registry_hold.text:
func (r *specRegistry) holdLaunch() func() {
	r.launches.RLock()
	return r.launches.RUnlock
}

registry_snapshot.text:
func (r *specRegistry) hostImageSnapshot() hostImageSnapshot {
	if r == nil {
		return hostImageSnapshot{}
	}
	// The roots are read under the spec lock, so the snapshot pairs the
	// adopted spec with the roots of the same instant. The root registry
	// never takes the spec lock, so the order cannot deadlock.
	r.mu.Lock()
	defer r.mu.Unlock()
	roots := r.roots.current()
	return hostImageSnapshot{images: slices.Clone(r.current.HostImages), launch: r.current.LaunchImage, roots: roots,
		version: fmt.Sprintf("%d/%s", r.current.Generation, strings.Join(slices.Sorted(maps.Keys(roots)), ","))}
}

registry_releaser.text:
func (r *specRegistry) releaser(actor, role, environment string) bool {
	if r == nil {
		return false
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	service, ok := r.current.Find(role)
	return ok && environment == r.identity.Environment && slices.Contains(service.Releasers, actor)
}

registry_controller.text:
func (r *specRegistry) controllerNode(cell, slot string) string {
	if r != nil {
		r.mu.Lock()
		defer r.mu.Unlock()
		for _, grant := range r.current.HostGrants {
			if grant.Controller == slot {
				return grant.Node
			}
		}
	}
	return naming.NATSServer(cell, slot)
}

registry_amended.text:
func (r *specRegistry) amended(ctx context.Context) (current cellspec.Spec, revision uint64, stored bool, err error) {
	r.mu.Lock()
	current = r.current
	r.mu.Unlock()
	entry, err := r.kv.Get(ctx, cellSpecKey)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return current, 0, false, nil
	}
	if err != nil {
		return cellspec.Spec{}, 0, false, fmt.Errorf("read cell spec: %w", err)
	}
	verified, err := r.verify(entry.Value(), nil)
	if newer := (*cellspec.NewerBinaryError)(nil); errors.As(err, &newer) {
		return current, entry.Revision(), false, fmt.Errorf("the stored %w; update this controller's binary first", newer)
	}
	if err != nil {
		slog.ErrorContext(ctx, "stored cell spec is invalid; amending the adopted spec", observability.ComponentKey, "cellspec",
			"revision", entry.Revision(), "error", err)
		return current, entry.Revision(), false, nil
	}
	if verified.Generation > current.Generation || sameSpec(verified.Spec, current) {
		return verified.Spec, entry.Revision(), true, nil
	}
	return current, entry.Revision(), false, nil
}

registry_diff.text:
func (r *specRegistry) diff(ctx context.Context, payload []byte) (specReply, error) {
	candidate, err := cellspec.Decode(payload)
	if err != nil {
		return specReply{}, err
	}
	if candidate.Identity != r.identity {
		return specReply{}, errors.New("cell spec names another deployment, cell or environment")
	}
	if err := r.validate(candidate); err != nil {
		return specReply{}, err
	}
	current, _, _, err := r.amended(ctx)
	if err != nil {
		return specReply{}, err
	}
	now := time.Now()
	if err := cellspec.VerifyHostImages(current, candidate, r.roots.current(), &now); err != nil {
		return specReply{}, err
	}
	plan, err := cellspec.Diff(r.withSigned(current), r.withSigned(candidate), r.fixed)
	if err != nil {
		return specReply{}, err
	}
	status := "planned"
	switch {
	case sameSpec(current, candidate):
		status = "unchanged"
	case candidate.Generation != current.Generation+1:
		status = "stale"
	}
	return specReply{Spec: candidate, Plan: &plan, Status: status}, nil
}

registry_apply.text:
func (r *specRegistry) apply(ctx context.Context, wire []byte, keyID string, epoch uint64, fencer authority.Fencer,
	hosts *host.Controller,
) (specReply, error) {
	now := time.Now()
	verified, err := r.verify(wire, &now)
	if err != nil {
		return specReply{}, err
	}
	spec := verified.Spec
	current, revision, stored, err := r.amended(ctx)
	// After a binary rollback no controller may read the stored record. The
	// root may replace it with the generation that follows it.
	newer := (*cellspec.NewerBinaryError)(nil)
	replacing := errors.As(err, &newer) && verified.RootSigned && spec.Generation == newer.Generation+1
	if err != nil && !replacing {
		return specReply{}, err
	}
	if stored && sameSpec(current, spec) {
		r.adopt(current, revision)
		return specReply{Spec: current, Status: "unchanged"}, nil
	}
	if !replacing && spec.Generation != current.Generation+1 {
		return specReply{}, fmt.Errorf("cell spec generation %d does not follow the current generation %d",
			spec.Generation, current.Generation)
	}
	// An accepted image stays allowed after its receipt expires; one the
	// amendment adds or changes must be qualified now, by a current root.
	if err := cellspec.VerifyHostImages(current, spec, r.roots.current(), &now); err != nil {
		return specReply{}, err
	}
	if changes := cellspec.AuthorityChanges(r.withSigned(current), r.withSigned(spec), r.fixed); len(changes) > 0 && !verified.RootSigned {
		return specReply{}, fmt.Errorf("cell spec generation %d widens authority (%s); a root must sign it",
			spec.Generation, strings.Join(changes, ", "))
	}
	// A spec that stops trusting the key that applies it could leave no
	// operator able to apply the next one: add the new signer first.
	if !reflect.DeepEqual(r.withSigned(current).Signers, r.withSigned(spec).Signers) {
		set, err := newSignerSet(r.effectiveSigners(spec))
		if err != nil {
			return specReply{}, fmt.Errorf("cell spec signers: %w", err)
		}
		if _, kept := set.trusted[keyID]; !kept {
			return specReply{}, errors.New("cell spec would no longer trust the key that applies it; " +
				"apply a spec that adds the new signer first, then remove this one")
		}
	}
	// Removing a role stops managing it, so its replicas must be gone first.
	// A role of the signed config keeps its signed profile instead.
	for _, service := range current.Services {
		_, kept := spec.Find(service.Role)
		if _, signed := r.fixed[service.Role]; kept || signed {
			continue
		}
		if r.removalReady != nil {
			if err := r.removalReady(ctx, service.Role); err != nil {
				return specReply{}, err
			}
		}
		desired, err := hosts.ListDesired(ctx, service.Role)
		if err != nil {
			return specReply{}, err
		}
		for _, allocation := range desired {
			if !allocation.Withdrawn {
				return specReply{}, fmt.Errorf("service %q still has a replica on %s; scale it to zero before removing it",
					service.Role, allocation.Node)
			}
		}
	}
	if err := fencer.Guard(ctx, epoch); err != nil {
		return specReply{}, err
	}
	if revision == 0 {
		revision, err = r.kv.Create(ctx, cellSpecKey, wire)
	} else {
		revision, err = r.kv.Update(ctx, cellSpecKey, wire, revision)
	}
	if err != nil {
		return specReply{}, fmt.Errorf("store cell spec: %w", err)
	}
	r.adopt(spec, revision)
	signer := map[bool]string{true: "root", false: "release leaf"}[verified.RootSigned]
	decisionlog.Record(ctx, decisionlog.Decision{Region: r.cell, Actor: decisionlog.Actor{Slice: "cellspec"},
		Kind: "cell_spec_applied", Subject: decisionlog.Subject{Kind: "region", ID: r.cell, Name: "cell spec"},
		Summary: fmt.Sprintf("Applied cell spec generation %d", spec.Generation),
		Reason:  fmt.Sprintf("Signed by the %s; it follows generation %d.", signer, current.Generation),
		Rule:    "cellspec.apply", Status: decisionlog.StatusSucceeded, Epoch: epoch,
		Attrs: map[string]string{"generation": strconv.FormatUint(spec.Generation, 10),
			"requires_binary": strconv.FormatUint(spec.RequiresBinary, 10), "signer": signer}})
	return specReply{Spec: spec, Status: "applied"}, nil
}

registry_serve.text:
func (r *specRegistry) serve(ctx context.Context, wire []byte, policy signerPolicy, fencer authority.Fencer,
	hosts *host.Controller,
) (specReply, error) {
	envelope, actor, err := verifyCellRequest(wire, policy, fencer)
	if err != nil {
		return specReply{}, err
	}
	switch envelope.Kind {
	case cellSpecGetKind:
		r.mu.Lock()
		defer r.mu.Unlock()
		return specReply{Spec: r.current}, nil
	case cellSpecDiffKind:
		return r.diff(ctx, envelope.Payload)
	}
	reply, err := r.apply(ctx, envelope.Payload, envelope.KeyID, envelope.Epoch, fencer, hosts)
	if err == nil {
		slog.InfoContext(ctx, "cell spec request", observability.ComponentKey, "cellspec", "actor", actor,
			"generation", reply.Spec.Generation, "status", reply.Status)
	}
	return reply, err
}

hostimage_args.text:
func operatorServiceHostImage(ctx context.Context, cfg Config, runtime *natscell.Runtime, allow, launch bool, imageID,
	receiptPath, delegationPath, out string, output io.Writer,
) error {
	if imageID == "" || allow != (receiptPath != "") || allow != (delegationPath != "") {
		return errors.New("service allow-image requires --image-id, --receipt and --delegation; revoke-image only --image-id")
	}
	image := cellspec.HostImage{ImageID: imageID}
	if allow {
		var err error
		if image.Receipt, err = readCanonicalEnvelope(receiptPath); err != nil {
			return fmt.Errorf("read image receipt: %w", err)
		}
		if image.Delegation, err = readCanonicalEnvelope(delegationPath); err != nil {
			return fmt.Errorf("read image delegation: %w", err)
		}
	}
	reply, err := requestCellSpec(ctx, cfg, runtime, cellSpecGetKind, []byte("{}"))
	if err != nil {
		return err
	}
	current := reply.Spec
	next := current
	next.Generation++
	if !allow && launch {
		if current.LaunchImage != imageID {
			return fmt.Errorf("image %s is not the launch image", imageID)
		}
		next.LaunchImage = ""
		return planSpec(ctx, cfg, runtime, current, next, out, output)
	}
	next.HostImages = slices.DeleteFunc(slices.Clone(current.HostImages), func(i cellspec.HostImage) bool { return i.ImageID == imageID })
	if allow {
		next.HostImages = append(next.HostImages, image)
		slices.SortFunc(next.HostImages, func(a, b cellspec.HostImage) int { return strings.Compare(a.ImageID, b.ImageID) })
	}
	switch {
	case launch:
		next.LaunchImage = imageID
	case !allow && next.LaunchImage == imageID:
		next.LaunchImage = ""
	}
	return planSpec(ctx, cfg, runtime, current, next, out, output)
}

canonical_envelope.text:
func readCanonicalEnvelope(path string) ([]byte, error) {
	data, err := readBoundedConfigFile(path)
	if err != nil {
		return nil, err
	}
	if _, err := trust.DecodeEnvelope(data); err != nil {
		return nil, err
	}
	return data, nil
}

bounded_file.text:
func readBoundedConfigFile(path string) ([]byte, error) {
	if path == "" {
		return nil, errors.New("managed regional configuration file is required")
	}
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() || info.Size() == 0 || info.Size() > maxConfigBytes {
		return nil, errors.New("managed regional configuration must be a bounded regular file")
	}
	data, err := io.ReadAll(io.LimitReader(file, maxConfigBytes+1))
	if err != nil {
		return nil, err
	}
	if len(data) == 0 || len(data) > maxConfigBytes {
		return nil, errors.New("managed regional configuration exceeds size limit")
	}
	return data, nil
}

request_spec.text:
func requestCellSpec(ctx context.Context, cfg Config, runtime *natscell.Runtime, kind string, payload []byte,
) (specReply, error) {
	data, err := requestLeader(ctx, cfg, runtime, kind, "cell-spec", payload)
	if err != nil {
		return specReply{}, err
	}
	var reply specReply
	if err := protocol.DecodeStrict(data, &reply, 3*cellspec.MaxSpecBytes); err != nil {
		return specReply{}, fmt.Errorf("decode %s reply: %w", kind, err)
	}
	if reply.Error != "" {
		return specReply{}, errors.New(reply.Error)
	}
	return reply, nil
}

request_authority.text:
func requestAuthority(ctx context.Context, cfg Config, runtime *natscell.Runtime, scope, kind, operation string,
	payload []byte,
) ([]byte, error) {
	policy, err := buildSignerPolicy(cfg)
	if err != nil {
		return nil, err
	}
	codec, err := policy.withOperator(cfg.Operator)
	if err != nil {
		return nil, err
	}
	epoch, err := observeOperatorAuthority(ctx, func(attempt context.Context) (authority.Snapshot, error) {
		return authority.Observe(attempt, runtime.JetStream(), scope)
	})
	if err != nil {
		return nil, err
	}
	now := time.Now().UTC()
	envelope, err := protocol.SignEnvelope(payload, protocol.EnvelopeScope{Region: cfg.NATS.Cell, Kind: kind,
		Actor: cfg.Operator.Actor, OperationID: entityid.New(), Generation: 1, Epoch: epoch,
	}, now, now.Add(time.Minute), codec.PrivateKey)
	if err != nil {
		return nil, err
	}
	wire, err := protocol.EncodeJSON(envelope)
	if err != nil {
		return nil, err
	}
	if len(wire) > maxRegistrationWireBytes {
		return nil, fmt.Errorf("%s request exceeds the controller request bound", kind)
	}
	for attempt := range 3 {
		requestCtx, cancel := context.WithTimeout(ctx, 15*time.Second)
		message, requestErr := runtime.Conn().RequestWithContext(requestCtx, hostRegistrationSubject(cfg.NATS.Cell), wire)
		cancel()
		if requestErr == nil {
			return message.Data, nil
		}
		if !errors.Is(requestErr, nats.ErrTimeout) && !errors.Is(requestErr, context.DeadlineExceeded) &&
			!errors.Is(requestErr, nats.ErrNoResponders) || attempt == 2 {
			return nil, fmt.Errorf("request %s: %w", kind, requestErr)
		}
	}
	return nil, fmt.Errorf("%s request exhausted", kind)
}

plan_spec.text:
func planSpec(ctx context.Context, cfg Config, runtime *natscell.Runtime, current, next cellspec.Spec, out string,
	output io.Writer,
) error {
	next.RequiresBinary = next.Level()
	encoded, err := cellspec.Encode(next)
	if err != nil {
		return err
	}
	planned, err := requestCellSpec(ctx, cfg, runtime, cellSpecDiffKind, encoded)
	if err != nil {
		return err
	}
	if planned.Plan == nil {
		return errors.New("cell spec diff reply has no plan")
	}
	plan := *planned.Plan
	if plan.Empty() {
		plan.To = current.Generation
		return printJSON(output, specPlanOutput{Plan: plan, Status: "unchanged"})
	}
	if out != "" {
		file, err := os.OpenFile(out, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
		if err != nil {
			return fmt.Errorf("write cell spec candidate: %w", err)
		}
		_, writeErr := file.Write(encoded)
		if err := errors.Join(writeErr, file.Close()); err != nil {
			_ = os.Remove(out)
			return fmt.Errorf("write cell spec candidate: %w", err)
		}
	}
	return printJSON(output, specPlanOutput{Plan: plan, Status: planned.Status, Candidate: out})
}

operator_apply.text:
func operatorSpecApply(ctx context.Context, cfg Config, runtime *natscell.Runtime, path string, output io.Writer) error {
	data, err := readBoundedConfigFile(path)
	if err != nil {
		return err
	}
	if len(data) > cellspec.MaxSignedBytes {
		return errors.New("signed cell spec exceeds its size bound")
	}
	// A spec for another region goes through the global home region.
	if target, _, err := relayTarget(data); err == nil && target != cfg.NATS.Cell {
		return operatorSpecRelay(ctx, cfg, runtime, target, data, output)
	}
	reply, err := requestCellSpec(ctx, cfg, runtime, cellSpecApplyKind, data)
	if err != nil {
		return err
	}
	roles := make([]string, 0, len(reply.Spec.Services))
	for _, service := range reply.Spec.Services {
		roles = append(roles, service.Role)
	}
	return printJSON(output, struct {
		Status         string   `json:"status"`
		Generation     uint64   `json:"generation"`
		RequiresBinary uint64   `json:"requires_binary"`
		Roles          []string `json:"roles"`
	}{reply.Status, reply.Spec.Generation, reply.Spec.RequiresBinary, roles})
}

relay.text:
func relayCellSpec(ctx context.Context, wire []byte, policy signerPolicy, global *globalControl, peers []string,
) (specReply, error) {
	request, actor, err := verifyCellRequest(wire, policy, global.authority)
	if err != nil {
		return specReply{}, err
	}
	var relay protocol.Envelope
	if err := protocol.DecodeStrict(request.Payload, &relay, maxRegistrationWireBytes); err != nil {
		return specReply{}, fmt.Errorf("decode the relayed request: %w", err)
	}
	if relay.Kind != cellSpecRelayKind || relay.Actor != actor || relay.KeyID != request.KeyID {
		return specReply{}, errors.New("the relayed request must be the publishing operator's own cell.spec.relay")
	}
	cell, err := protocol.RegionToken(relay.Region)
	if err != nil || !slices.Contains(peers, cell) {
		return specReply{}, fmt.Errorf("cell %q is not an interregion peer of this region", relay.Region)
	}
	target, generation, err := relayTarget(relay.Payload)
	if err != nil {
		return specReply{}, err
	}
	if target != cell {
		return specReply{}, fmt.Errorf("the spec is for cell %q, not %q", target, cell)
	}
	// A spec this binary cannot decode never travels, unless it only needs
	// a newer binary than the home runs: the target may understand it.
	spec, err := cellspec.Candidate(relay.Payload)
	if newer := (*cellspec.NewerBinaryError)(nil); err != nil && !errors.As(err, &newer) {
		return specReply{}, fmt.Errorf("decode the relayed cell spec: %w", err)
	}
	spec.Generation = generation
	// An older spec never displaces the one waiting; an equal generation
	// may (a renewed signature). The append is conditional on the record
	// this check saw.
	olderThanWaiting := func(prior []byte) error {
		var waiting protocol.Envelope
		if prior == nil || protocol.DecodeStrict(prior, &waiting, maxRegistrationWireBytes) != nil {
			return nil
		}
		if _, pending, err := relayTarget(waiting.Payload); err == nil && generation < pending {
			return fmt.Errorf("cell %s already has generation %d waiting; generation %d is older", target, pending, generation)
		}
		return nil
	}
	if _, err := global.writer.PutDocument(ctx, request.Epoch, globalcontrol.KindCellSpec, target, request.Payload,
		olderThanWaiting); err != nil {
		return specReply{}, err
	}
	slog.InfoContext(ctx, "cell spec relayed", observability.ComponentKey, "cellspec", "actor", actor, "cell", target,
		"generation", generation)
	return specReply{Spec: spec, Status: "relayed"}, nil
}

relay_follow.text:
func (r *specRegistry) followRelayedSpecs(ctx context.Context, reader *globalcontrol.Reader, policy signerPolicy,
	fencer authority.Fencer, hosts *host.Controller,
) error {
	var reported string
	return reader.Follow(ctx, globalcontrol.KindCellSpec, r.cell, relayRecheck,
		func(ctx context.Context, document globalcontrol.Document) {
			snapshot := fencer.Current()
			if !snapshot.CanMutate() {
				return
			}
			_, err := r.applyRelayed(ctx, document.Payload, policy, snapshot.Epoch, fencer, hosts)
			if errors.Is(err, authority.ErrFenced) || errors.Is(err, authority.ErrNotLeader) {
				return
			}
			outcome := fmt.Sprint(document.Sequence, err)
			if err != nil && outcome != reported {
				slog.ErrorContext(ctx, "relayed cell spec refused; keeping the current spec", observability.ComponentKey, "cellspec",
					"sequence", document.Sequence, "error", err)
			}
			reported = outcome
		})
}

relay_apply.text:
func (r *specRegistry) applyRelayed(ctx context.Context, wire []byte, policy signerPolicy, epoch uint64,
	fencer authority.Fencer, hosts *host.Controller,
) (specReply, error) {
	var relay protocol.Envelope
	if err := protocol.DecodeStrict(wire, &relay, maxRegistrationWireBytes); err != nil {
		return specReply{}, fmt.Errorf("decode the relayed request: %w", err)
	}
	trusted, ok := policy.trusted(relay.KeyID)
	if !ok || trusted.Actor != relay.Actor {
		return specReply{}, errors.New("the relayed request's signer is not trusted in this cell")
	}
	if err := protocol.VerifyEnvelope(relay, protocol.EnvelopeScope{Region: policy.cell, Kind: cellSpecRelayKind,
		Actor: trusted.Actor, OperationID: relay.OperationID, Generation: 1,
	}, trusted.PublicKey, time.Now().UTC(), protocol.VerifyPolicy{MaxLifetime: cellspec.MaxSpecLifetime, ClockSkew: 30 * time.Second}); err != nil {
		return specReply{}, fmt.Errorf("verify the relayed request: %w", err)
	}
	return r.apply(ctx, relay.Payload, relay.KeyID, epoch, fencer, hosts)
}

global_put.text:
func (w *Writer) put(ctx context.Context, epoch uint64, kind Kind, key string, generation uint64, payload []byte,
	admit func(prior []byte) error,
) (uint64, error) {
	if epoch == 0 {
		return 0, authority.ErrFenced
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	if err := w.fencer.Guard(ctx, epoch); err != nil {
		return 0, err
	}
	for range maxAppendAttempts {
		lastSequence, err := w.establishTerm(ctx, epoch)
		if err != nil {
			return 0, err
		}
		next := max(generation, 1)
		prior, priorSequence, err := w.read(ctx, kind, key)
		switch {
		case errors.Is(err, ErrNotFound):
		case err != nil:
			return 0, err
		case priorSequence > lastSequence:
			continue
		case (generation == 0 || prior.Generation == generation) && bytes.Equal(prior.Payload, payload):
			// An identical retry after an unknown publish outcome is idempotent.
			return priorSequence, nil
		case generation == 0:
			next = prior.Generation + 1
		case generation <= prior.Generation:
			return 0, ErrStaleRecord
		}
		if epoch < prior.Epoch {
			return 0, authority.ErrFenced
		}
		if admit != nil {
			if err := admit(prior.Payload); err != nil {
				return 0, err
			}
		}
		data, err := protocol.EncodeJSON(record{
			Version: recordVersion, Kind: kind, Key: key, Generation: next, Epoch: epoch, Payload: payload,
		})
		if err != nil {
			return 0, err
		}
		if w.beforePublish != nil {
			w.beforePublish()
		}
		message := nats.NewMsg(subject(kind, key))
		message.Data = data
		message.Header.Set(EpochHeader, strconv.FormatUint(epoch, 10))
		publishCtx, cancel := context.WithTimeout(ctx, apiTimeout)
		ack, err := w.js.PublishMsg(publishCtx, message,
			jetstream.WithExpectStream(StreamName),
			jetstream.WithExpectLastSequence(lastSequence),
			jetstream.WithExpectLastSequenceForSubject(priorSequence, subject(kind, key)),
			jetstream.WithMsgID(string(kind)+"."+key+"."+strconv.FormatUint(next, 10)),
		)
		cancel()
		if wrongLastSequence(err) {
			// Another append won: a newer term barrier or a concurrent write.
			// The next attempt observes it and fences or re-checks the CAS.
			continue
		}
		if err != nil {
			return 0, fmt.Errorf("publish global %s record: %w", kind, err)
		}
		if ack.Duplicate {
			// The message ID was seen; only an identical stored record is success.
			stored, sequence, readErr := w.read(ctx, kind, key)
			if readErr != nil || stored.Generation != next || !bytes.Equal(stored.Payload, payload) {
				return 0, ErrConflict
			}
			return sequence, nil
		}
		return ack.Sequence, nil
	}
	return 0, ErrConflict
}

global_read.text:
func (r *Reader) read(ctx context.Context, kind Kind, key string) (record, uint64, error) {
	if r == nil || r.stream == nil {
		return record{}, 0, errors.New("global control reader is not open")
	}
	readCtx, cancel := context.WithTimeout(ctx, apiTimeout)
	defer cancel()
	message, err := r.stream.GetLastMsgForSubject(readCtx, subject(kind, key))
	if r.mirror && (err == nil || errors.Is(err, jetstream.ErrMsgNotFound)) {
		// Checked after the read: no gap up to the mirror's last sequence
		// now means no newer record for this subject was skipped before it.
		if gapErr := r.checkMirrorGapFree(readCtx); gapErr != nil {
			return record{}, 0, gapErr
		}
	}
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return record{}, 0, ErrNotFound
	}
	if err != nil {
		return record{}, 0, err
	}
	var stored record
	if err := protocol.DecodeStrict(message.Data, &stored, maxMessageBytes); err != nil ||
		stored.Version != recordVersion || stored.Kind != kind || stored.Key != key ||
		stored.Generation == 0 || stored.Epoch == 0 {
		return record{}, 0, ErrRecordCorrupt
	}
	if !epochHeaderMatches(message.Header, stored.Epoch) {
		return record{}, 0, ErrRecordCorrupt
	}
	return stored, message.Sequence, nil
}

signers_build.text:
func buildSignerPolicy(cfg Config) (signerPolicy, error) {
	set, err := newSignerSet(cfg.Controller.TrustedSigners)
	if err != nil {
		return signerPolicy{}, err
	}
	signers := &atomic.Pointer[signerSet]{}
	signers.Store(&set)
	releases := &atomic.Pointer[delegatedReleaseSigner]{}
	return signerPolicy{
		codec: delivery.Ed25519Codec{Cell: cfg.NATS.Cell, Lifetime: time.Minute, MaxLifetime: 5 * time.Minute,
			ClockSkew: 30 * time.Second, Lookup: func(keyID string) (delivery.TrustedSigner, bool) {
				if trusted, ok := signers.Load().trusted[keyID]; ok {
					return trusted, true
				}
				if delegated := releases.Load(); delegated.current() && delegated.keyID == keyID {
					return delivery.TrustedSigner{Actor: delegated.actor, PublicKey: delegated.key}, true
				}
				return delivery.TrustedSigner{}, false
			}},
		signers: signers, release: releases, cell: cfg.NATS.Cell,
	}, nil
}

signers_replace.text:
func (p signerPolicy) replaceSigners(grants []TrustedSignerConfig) error {
	set, err := newSignerSet(grants)
	if err != nil {
		return err
	}
	p.signers.Store(&set)
	return nil
}

authorize_artifact.text:
func (p signerPolicy) authorizeArtifact(_ context.Context, actor string, record delivery.ArtifactRecord) error {
	if record.Cell != p.cell || !p.mayRelease(actor, record.Role, record.Environment, record.Source.Repository) {
		return delivery.ErrUnauthorized
	}
	return nil
}

may_release.text:
func (p signerPolicy) mayRelease(actor, role, environment, repository string) bool {
	if strings.HasPrefix(actor, release.DelegatedReleaseActorPrefix) {
		delegated := p.release.Load()
		return delegated.current() && actor == delegated.actor && environment == delegated.delegation.Environment &&
			delegated.delegation.MayRelease(role, repository)
	}
	grant, exists := p.grant(actor)
	if !exists || len(grant.Repositories) > 0 && !slices.Contains(grant.Repositories, repository) {
		return false
	}
	return slices.Contains(grant.Roles, role) && slices.Contains(grant.Environments, environment) ||
		p.services.releaser(actor, role, environment)
}

fleet_ensure.text:
func (f *fleet) EnsureHost(ctx context.Context, request EnsureRequest) (Instance, error) {
	if !validCreateKey(request.CreateKey) || !slices.Contains(f.config.FaultDomains, request.FaultDomain) {
		return Instance{}, errors.New("OCI host launch has an invalid create key or unsupported fault domain")
	}
	if !f.memberName(request.Name, false) {
		return Instance{}, fmt.Errorf("OCI host launch name %q is not a member name of this cell", request.Name)
	}
	if !validManagedPrivateIP(request.PrivateIP) {
		return Instance{}, errors.New("OCI host launch requires a signed private IPv4 address")
	}
	if request.Shape != f.config.Shape || !validComputeProfile(request.Shape, request.WholeOCPUs,
		request.MemoryInGBs, request.PlacementProfileDigest, request.PlacementGeneration) {
		return Instance{}, ErrPlacementProfileMismatch
	}
	choice, err := f.launchImage(ctx, request.CreateKey)
	if err != nil {
		return Instance{}, err
	}
	image := choice.image
	descriptor, err := f.hostBootDescriptor(request, image)
	if err != nil {
		return Instance{}, fmt.Errorf("%w: %v", ErrHostBootBindingMismatch, err)
	}
	descriptorWire, err := descriptor.CanonicalBytes()
	if err != nil {
		return Instance{}, fmt.Errorf("%w: encode descriptor: %v", ErrHostBootBindingMismatch, err)
	}
	descriptorDigest, err := descriptor.Digest()
	if err != nil {
		return Instance{}, fmt.Errorf("%w: digest descriptor: %v", ErrHostBootBindingMismatch, err)
	}
	epoch, err := f.currentEpoch()
	if err != nil {
		return Instance{}, err
	}
	release, err := f.beginActiveWorkloadEffect(ctx, epoch, descriptor.DatabaseID, descriptor.PartitionID)
	if err != nil {
		return Instance{}, err
	}
	defer release()
	if err := f.verifyLaunchScope(ctx, descriptor, request.CreateKey); err != nil {
		return Instance{}, err
	}
	intent := f.intent(actionLaunch, request.CreateKey, "", request.CreateKey, "", request.FaultDomain, "")
	intent.Shape = request.Shape
	intent.PrivateIP = request.PrivateIP
	intent.WholeOCPUs = request.WholeOCPUs
	intent.MemoryInGBs = request.MemoryInGBs
	intent.PlacementProfileDigest = request.PlacementProfileDigest
	intent.PlacementGeneration = request.PlacementGeneration
	intent.ImageID = image
	intent.BootDescriptor = string(descriptorWire)
	intent.BootDescriptorSHA256 = descriptorDigest
	if err := f.recordIntent(ctx, epoch, intent); err != nil {
		return Instance{}, err
	}
	priorResult, hasPriorResult, err := f.journal.GetResult(ctx, intent)
	if err != nil {
		return Instance{}, fmt.Errorf("read OCI host operation result: %w", err)
	}
	operationIntent := priorResult.Intent
	if operationIntent.CreatedAt.IsZero() {
		operationIntent = intent
	}
	cloud, identity, found, err := f.findByCreateKey(ctx, request.CreateKey)
	if err != nil {
		if hasPriorResult && !priorResult.Unknown && isNotFound(err) {
			return Instance{}, createRecoveryHold(resourceMemberHost, request.CreateKey, "the previously confirmed instance is missing")
		}
		return Instance{}, err
	}
	if found {
		owned, err := f.journal.IsOwnedInstance(ctx, identity)
		if err != nil {
			return Instance{}, fmt.Errorf("read OCI host ownership journal: %w", err)
		}
		if owned {
			if hasPriorResult && !priorResult.Unknown && priorResult.ResourceID != cloud.ID {
				return Instance{}, createRecoveryHold(resourceMemberHost, request.CreateKey, "the observed instance differs from the immutable confirmed result")
			}
			if cloud.FaultDomain != request.FaultDomain {
				return Instance{}, fmt.Errorf("%w: create key is bound to a different fault domain", ErrForeignResource)
			}
			if !cloudMatchesPlacementProfile(cloud, operationIntent) {
				return Instance{}, fmt.Errorf("%w: observed instance does not match the immutable launch intent", ErrPlacementProfileMismatch)
			}
			if cloud.PrivateIP != operationIntent.PrivateIP {
				return Instance{}, fmt.Errorf("%w: observed private IP differs from immutable launch intent", ErrPlacementProfileMismatch)
			}
			// The launch receipt is immutable; the live ETag belongs to this
			// observation and will fence the next tag/termination operation.
			if err := f.captureBootBinding(ctx, epoch, cloud, identity); err != nil {
				return Instance{}, err
			}
			return f.instanceFromCloud(ctx, cloud, identity, operationIntent)
		}
		if !hasPriorResult || !priorResult.Unknown {
			if hasPriorResult && !priorResult.Unknown {
				return Instance{}, createRecoveryHold(resourceMemberHost, request.CreateKey, "the confirmed instance is no longer positively owned")
			}
			return Instance{}, fmt.Errorf("%w: instance %s has matching tags but no durable provider attempt or ownership", ErrForeignResource, cloud.ID)
		}
	} else if hasPriorResult && !priorResult.Unknown {
		return Instance{}, createRecoveryHold(resourceMemberHost, request.CreateKey, "the previously confirmed instance is missing")
	}
	if err := checkCreateRetryWindow(resourceMemberHost, request.CreateKey, operationIntent, f.now()); err != nil {
		return Instance{}, err
	}
	node := hostNode(f.config, request.CreateKey)
	launch := LaunchRequest{
		DisplayName: request.Name,
		CreateKey:   request.CreateKey,
		Node:        node,
		RetryToken: retryToken(strings.Join([]string{
			f.config.Owner, string(f.config.Region), fmt.Sprint(f.config.Generation), request.CreateKey,
		}, ":")),
		FaultDomain:            operationIntent.FaultDomain,
		PrivateIP:              operationIntent.PrivateIP,
		Shape:                  operationIntent.Shape,
		WholeOCPUs:             operationIntent.WholeOCPUs,
		MemoryInGBs:            operationIntent.MemoryInGBs,
		PlacementProfileDigest: operationIntent.PlacementProfileDigest,
		PlacementGeneration:    operationIntent.PlacementGeneration,
		ImageID:                operationIntent.ImageID,
		BootVolumeGB:           f.config.BootVolumeGB,
		BootVolumeVPUsPerGB:    f.config.BootVolumeVPUsPerGB,
		BootDescriptor:         operationIntent.BootDescriptor,
		FreeformTags: placementProfileTags(
			hostTags(f.config, request.CreateKey), operationIntent.PlacementProfileDigest, operationIntent.PlacementGeneration,
		),
	}
	// The image must still be allowed and qualify right before the provider
	// launch: a replay may run hours after it was journaled, and the cell
	// spec may change between a new launch's choice and this launch.
	if choice.image != operationIntent.ImageID {
		choice = launchChoice{image: operationIntent.ImageID}
	}
	releaseFence, err := f.admitLaunch(ctx, choice)
	if err != nil {
		return Instance{}, err
	}
	fenced := true
	defer func() {
		if fenced {
			releaseFence()
		}
	}()
	if err := f.guard(ctx, epoch); err != nil {
		return Instance{}, err
	}
	if err := checkCreateRetryWindow(resourceMemberHost, request.CreateKey, operationIntent, f.now()); err != nil {
		return Instance{}, err
	}
	created, launchErr := f.provider.LaunchInstance(ctx, launch)
	if launchErr != nil {
		if err := f.guard(ctx, epoch); err != nil {
			return Instance{}, errors.Join(ErrOutcomeUnknown, launchErr, err, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
		}
		if err := checkCreateRetryWindow(resourceMemberHost, request.CreateKey, operationIntent, f.now()); err != nil {
			return Instance{}, errors.Join(err, launchErr, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
		}
		created, launchErr = f.provider.LaunchInstance(ctx, launch)
	}
	fenced = false
	releaseFence()
	if launchErr != nil || created.ID == "" {
		unknownErr := errors.Join(ErrOutcomeUnknown, launchErr, errors.New("OCI launch response did not confirm an instance ID"))
		return Instance{}, errors.Join(unknownErr, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
	}
	cloud, identity, found, err = f.findByCreateKey(ctx, request.CreateKey)
	if err != nil {
		unknownErr := errors.Join(ErrOutcomeUnknown, err)
		return Instance{}, errors.Join(unknownErr, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
	}
	if !found || cloud.ID != created.ID {
		unknownErr := fmt.Errorf("%w: launched instance was not positively re-observed by create key", ErrOutcomeUnknown)
		return Instance{}, errors.Join(unknownErr, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
	}
	if cloud.FaultDomain != request.FaultDomain {
		return Instance{}, fmt.Errorf("%w: create key is bound to a different fault domain", ErrForeignResource)
	}
	if !cloudMatchesPlacementProfile(cloud, operationIntent) {
		unknownErr := fmt.Errorf("%w: %w: launched instance does not match the immutable launch intent", ErrOutcomeUnknown, ErrPlacementProfileMismatch)
		return Instance{}, errors.Join(unknownErr, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
	}
	if cloud.PrivateIP != operationIntent.PrivateIP {
		unknownErr := fmt.Errorf("%w: %w: launched private IP differs from immutable launch intent", ErrOutcomeUnknown, ErrPlacementProfileMismatch)
		return Instance{}, errors.Join(unknownErr, f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, Unknown: true}))
	}
	if err := f.recordResult(ctx, epoch, OperationResult{Intent: operationIntent, ResourceID: cloud.ID, ETag: cloud.ETag}); err != nil {
		return Instance{}, err
	}
	if err := f.captureBootBinding(ctx, epoch, cloud, identity); err != nil {
		return Instance{}, err
	}
	return f.instanceFromCloud(ctx, cloud, identity, operationIntent)
}

fleet_epoch.text:
func (f *fleet) currentEpoch() (uint64, error) {
	snapshot := f.fencer.Current()
	if !snapshot.CanMutate() {
		return 0, authority.ErrNotLeader
	}
	return snapshot.Epoch, nil
}

fleet_active.text:
func (f *fleet) beginActiveWorkloadEffect(ctx context.Context, epoch uint64, databaseID, partitionID string) (func(), error) {
	gate, ok := f.fencer.(activeWorkloadFencer)
	if !ok || databaseID == "" || partitionID == "" {
		return nil, errors.New("OCI active workload effect requires a terminal-aware authority gate and workload scope")
	}
	return gate.BeginActiveWorkloadEffect(ctx, epoch, authority.WorkloadScope{DatabaseID: databaseID, PartitionID: partitionID})
}

active_effect.text:
func (r *Runtime) BeginActiveWorkloadEffect(ctx context.Context, epoch uint64, scope WorkloadScope) (func(), error) {
	if ctx != nil {
		if state, ok := ctx.Value(workloadEffectContextKey{}).(*workloadEffectContext); ok {
			state.mu.Lock()
			if held := state.active[scope]; held != nil {
				if held.runtime != r || held.epoch != epoch {
					state.mu.Unlock()
					return nil, ErrFenced
				}
				held.refs++
				state.mu.Unlock()
				release := sync.OnceFunc(func() { state.release(scope) })
				if err := r.Guard(ctx, epoch); err != nil {
					release()
					return nil, err
				}
				return release, nil
			}
			gate := r.workloadGate(scope)
			gate.RLock()
			if err := r.requireNoTerminalIntent(ctx, scope.DatabaseID, scope.PartitionID); err != nil {
				gate.RUnlock()
				state.mu.Unlock()
				return nil, err
			}
			if err := r.Guard(ctx, epoch); err != nil {
				gate.RUnlock()
				state.mu.Unlock()
				return nil, err
			}
			state.active[scope] = &heldWorkloadEffect{runtime: r, epoch: epoch, gate: gate, refs: 1}
			state.mu.Unlock()
			return sync.OnceFunc(func() { state.release(scope) }), nil
		}
	}
	release, err := r.beginWorkloadGate(ctx, scope)
	if err != nil {
		return nil, err
	}
	if err := r.requireNoTerminalIntent(ctx, scope.DatabaseID, scope.PartitionID); err != nil {
		release()
		return nil, err
	}
	if err := r.Guard(ctx, epoch); err != nil {
		release()
		return nil, err
	}
	return release, nil
}

terminal_required.text:
func (r *Runtime) requireNoTerminalIntent(ctx context.Context, databaseID, partitionID string) error {
	_, err := r.ReadTerminalIntent(ctx, databaseID, partitionID)
	if errors.Is(err, ErrNotFound) {
		return nil
	}
	if err == nil {
		return ErrFenced
	}
	return err
}

terminal_read.text:
func (r *Runtime) ReadTerminalIntent(ctx context.Context, databaseID, partitionID string) (LogEntry, error) {
	subjectKey, err := placementIntentSubjectKey(databaseID, partitionID)
	if err != nil {
		return LogEntry{}, err
	}
	if r == nil {
		return LogEntry{}, ErrFenced
	}
	r.readMu.Lock()
	defer r.readMu.Unlock()
	entry, err := readMutation(ctx, r.readStream, r.config.Scope, MutationTerminalIntent, subjectKey)
	if err != nil {
		return LogEntry{}, err
	}
	intent, err := decodeTerminalIntent(entry.Payload)
	if err != nil || intent.Cell != r.config.Scope || intent.DatabaseID != databaseID ||
		intent.PartitionID != partitionID || intent.OperationID != entry.OperationID {
		return LogEntry{}, errors.New("terminal control log identity is invalid")
	}
	return entry, nil
}

mutation_read.text:
func readMutation(ctx context.Context, stream jetstream.Stream, scope string, kind HostMutationKind, subjectKey string) (LogEntry, error) {
	subject := mutationSubject(scope, kind, subjectKey)
	entry, err := stream.GetLastMsgForSubject(ctx, subject)
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return LogEntry{}, ErrNotFound
	}
	if err != nil {
		return LogEntry{}, err
	}
	record, err := decodeControlRecord(entry.Data)
	if err != nil || record.Scope != scope || record.Kind != kind || record.SubjectKey != subjectKey || record.Epoch == 0 {
		return LogEntry{}, errors.New("host control log entry is invalid")
	}
	return LogEntry{
		Kind: record.Kind, SubjectKey: record.SubjectKey, OperationID: record.OperationID,
		Epoch: record.Epoch, Sequence: entry.Sequence, CreatedAt: entry.Time, Payload: bytes.Clone(record.Payload),
	}, nil
}

authority_guard.text:
func (r *Runtime) Guard(ctx context.Context, expectedEpoch uint64) error {
	if r == nil {
		return ErrNotLeader
	}
	if guard, ok := ctx.Value(verificationGuardKey{}).(*verificationGuard); ok {
		return r.guardVerification(ctx, expectedEpoch, guard)
	}
	if r.checkClock() != nil {
		return ErrClockUnhealthy
	}
	r.mu.Lock()
	current := r.Current()
	if !current.CanMutate() || current.Scope != r.config.Scope || current.DeploymentID != r.config.DeploymentID || current.CandidateID != r.config.CandidateID || current.OwnerID != r.ownerID {
		wasLocalLeader := current.Leader && current.CandidateID == r.config.CandidateID && current.OwnerID == r.ownerID
		r.mu.Unlock()
		r.logSnapshotTransition()
		if wasLocalLeader {
			r.recordFailure(stageFailure("guard_precondition", ErrNotLeader))
		}
		return ErrNotLeader
	}
	if expectedEpoch == 0 || current.Epoch != expectedEpoch {
		r.mu.Unlock()
		return ErrFenced
	}
	var lastErr error
	for range 8 {
		err := r.guardLocked(ctx, expectedEpoch)
		if !errors.Is(err, ErrConflict) {
			r.mu.Unlock()
			r.logSnapshotTransition()
			if err != nil {
				r.recordFailure(err)
			}
			return err
		}
		lastErr = err
	}
	if lastErr == nil {
		lastErr = stageFailure("guard_retry", ErrConflict)
	}
	r.mu.Unlock()
	r.logSnapshotTransition()
	r.recordFailure(lastErr)
	return lastErr
}

accepted.text:
func newAcceptedSpecTrust(t *testing.T, cfg *Config) {
	t.Helper()
	accepted := bootstrapstart.AcceptedIdentity{DeploymentID: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
		Cell: cfg.NATS.Cell, Environment: "test"}
	roots := testSpecRoots(t)
	if spec := cfg.Controller.SpecTrust; spec != nil {
		accepted.DeploymentID, accepted.Environment = spec.DeploymentID, spec.Environment
		wire, err := os.ReadFile(spec.RootPublicKeyFile)
		if err != nil {
			t.Fatal(err)
		}
		block, _ := pem.Decode(wire)
		if block == nil || block.Type != "PUBLIC KEY" {
			t.Fatal("spec trust root is not a PEM public key")
		}
		key, err := x509.ParsePKIXPublicKey(block.Bytes)
		if err != nil {
			t.Fatal(err)
		}
		public, ok := key.(ed25519.PublicKey)
		if !ok {
			t.Fatal("spec trust root is not Ed25519")
		}
		roots, err = trust.ParseKeyring(public)
		if err != nil {
			t.Fatal(err)
		}
	}
	cfg.Controller.SpecTrust = nil
	previous := specAcceptedInputs
	specAcceptedInputs = func() (bootstrapstart.AcceptedIdentity, bootstrapstart.TrustInputs, error) {
		chain := trust.RootChain{Version: 1}
		identity := trust.ChainIdentity{DeploymentID: accepted.DeploymentID, Cell: accepted.Cell, Environment: accepted.Environment}
