	if r.fake {
		serve := r.serve
		if serve == nil {
			serve = fakeMember
		}
		stop, exited, err := serve(w)
		if err != nil {
			return err
		}
		r.mu.Lock()
		defer r.mu.Unlock()
		r.stop, r.exited, r.workload = stop, exited, w
		return nil
	}
	log, err := os.OpenFile(r.log, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
	if err != nil {
		return err
	}
	defer log.Close()
	command := exec.Command(w.Executable, w.Args...)
	command.Env = []string{"HOME=/", "LANG=C", "PATH=/usr/bin:/bin"}
	for key, value := range w.Env {
		command.Env = append(command.Env, key+"="+value)
	}
	command.Stdout, command.Stderr = log, log
	if err := command.Start(); err != nil {
		return err
	}
	exited := make(chan struct{})
	go func() {
		_ = command.Wait()
		close(exited)
	}()
	r.mu.Lock()
	defer r.mu.Unlock()
	r.command, r.exited, r.workload = command, exited, w
	return nil
}

child_observe.text:
func (r *childRunner) Observe(_ context.Context, role string) (host.Observation, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.command == nil && r.stop == nil {
		return host.Observation{Role: role}, nil
	}
	observed := host.Observation{Role: role, Digest: r.workload.Digest, Fingerprint: r.workload.Fingerprint,
		Running: true, PID: os.Getpid()}
	select {
	case <-r.exited:
		// Like the cgroup runner, an exited process keeps its record.
		observed.Running, observed.PID = false, 0
	default:
	}
	return observed, nil
}

config_members.text:
func configMembers(typ reflect.Type) []string {
	var members []string
	var walk func(path string, typ reflect.Type, stack []reflect.Type)
	walk = func(path string, typ reflect.Type, stack []reflect.Type) {
		for typ.Kind() == reflect.Pointer || typ.Kind() == reflect.Slice || typ.Kind() == reflect.Map {
			typ = typ.Elem()
		}
		if typ.Kind() != reflect.Struct || !strings.HasPrefix(typ.PkgPath(), "github.com/TerraScale/") ||
			slices.Contains(stack, typ) {
			return
		}
		for index := range typ.NumField() {
			field := typ.Field(index)
			if !field.IsExported() || field.Tag.Get("json") == "-" {
				continue
			}
			member := path + "." + field.Name
			members = append(members, member+" "+jsonShape(field.Type)+" "+string(field.Tag))
			walk(member, field.Type, append(stack, typ))
		}
	}
	walk("", typ, nil)
	slices.Sort(members)
	return members
}

json_shape.text:
func jsonShape(typ reflect.Type) string {
	switch typ.Kind() {
	case reflect.Pointer:
		return "*" + jsonShape(typ.Elem())
	case reflect.Slice:
		return "[]" + jsonShape(typ.Elem())
	case reflect.Map:
		return "map[" + jsonShape(typ.Key()) + "]" + jsonShape(typ.Elem())
	}
	if strings.HasPrefix(typ.PkgPath(), "github.com/TerraScale/") {
		return typ.Kind().String()
	}
	return typ.String()
}

